mapper.select:
SELECT u.*, r.role_name AS userRoleName FROM t_zgsq_user u LEFT JOIN t_zgsq_role r ON u.role_id = r.role_id AND r.deleted = 0 WHERE u.deleted = 0
AND u.user_name LIKE CONCAT('%', #{userName}, '%')
AND u.user_status = #{userStatus}
AND u.user_real_name LIKE CONCAT('%', #{userRealName}, '%')
ORDER BY u.user_id DESC LIMIT #{offset}, #{pageSize}
